#!/usr/bin/env python3
"""Add grouped, commit-linked notes to a ShaaenFCT GitHub Release.

Existing release text is preserved; only the generated section is replaced.
Usage: python3 .github/scripts/update_release_notes.py [vX.Y.Z]
Requires GH_TOKEN with contents:write permission and GitHub CLI (gh).
"""
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

START = "<!-- ShaaenFCT:changelog:start -->"
END = "<!-- ShaaenFCT:changelog:end -->"
VERSION_RE = re.compile(r"^v(\d+)\.(\d+)\.(\d+)$")
CONVENTIONAL_RE = re.compile(r"^(feat|fix|perf|refactor|docs|build|chore|ci|test|style)(?:\([^)]*\))?!?:\s*(.+)$", re.I)


def gh(*args):
    return subprocess.check_output(["gh", *args], text=True).strip()


def api(path):
    return json.loads(gh("api", path))


def semver(tag):
    match = VERSION_RE.fullmatch(tag)
    return tuple(map(int, match.groups())) if match else None


def grouped_commits(commits, repository):
    sections = {"Ajouts": [], "Corrections": [], "Maintenance et documentation": []}
    for item in commits:
        sha = item["sha"]
        subject = item["commit"]["message"].splitlines()[0].strip()
        match = CONVENTIONAL_RE.match(subject)
        kind, title = (match.group(1).lower(), match.group(2).strip()) if match else ("", subject)
        if kind == "feat" or re.match(r"^(add|added|ajout|ajouter)\b", subject, re.I):
            section = "Ajouts"
        elif kind == "fix" or re.match(r"^(fix|fixed|correct|correction)\b", subject, re.I):
            section = "Corrections"
        else:
            section = "Maintenance et documentation"
        # Escape Markdown special characters in commit subjects.
        title = title.replace("\\", "\\\\").replace("[", "\\[").replace("]", "\\]")
        sections[section].append(
            f"- {title} ([`{sha[:7]}`](https://github.com/{repository}/commit/{sha}))"
        )
    return sections


def main():
    repository = os.environ.get("GITHUB_REPOSITORY", "NLshaen/ShaaenFCT")
    if repository != "NLshaen/ShaaenFCT":
        raise SystemExit("Refusing to modify an unexpected repository")
    requested_tag = sys.argv[1].strip() if len(sys.argv) > 1 else ""
    if not requested_tag:
        requested_tag = api(f"repos/{repository}/releases/latest")["tag_name"]
    version = semver(requested_tag)
    if not version:
        raise SystemExit(f"Invalid release tag: {requested_tag}")

    release = api(f"repos/{repository}/releases/tags/{requested_tag}")
    all_tags = api(f"repos/{repository}/tags?per_page=100")
    previous_tags = [(semver(tag["name"]), tag["name"]) for tag in all_tags]
    previous_tags = [(ver, name) for ver, name in previous_tags if ver and ver < version]
    if not previous_tags:
        print(f"No earlier semver tag: leaving {requested_tag} unchanged")
        return
    previous = max(previous_tags)[1]
    comparison = api(f"repos/{repository}/compare/{previous}...{requested_tag}?per_page=100")
    commits = comparison.get("commits", [])
    if comparison.get("total_commits", 0) > len(commits):
        raise SystemExit("Comparison is truncated; refusing to publish an incomplete changelog")

    sections = grouped_commits(commits, repository)
    generated = [
        START,
        f"## Modifications depuis {previous}",
        "",
        "### Ajouts",
        *(sections["Ajouts"] or ["- Aucun commit d'ajout distinct pour cette version."]),
        "",
        "### Corrections",
        *(sections["Corrections"] or ["- Aucun commit de correction distinct pour cette version."]),
        "",
        "### Maintenance et documentation",
        *(sections["Maintenance et documentation"] or ["- Aucun."]),
        "",
        f"**Comparaison complète :** https://github.com/{repository}/compare/{previous}...{requested_tag}",
        END,
    ]
    existing = release.get("body") or ""
    if (START in existing) != (END in existing):
        raise SystemExit("Mismatched autogenerated changelog markers; no changes made")
    if START in existing:
        preserved = re.sub(re.escape(START) + r".*?" + re.escape(END), "", existing, count=1, flags=re.S).strip()
    else:
        preserved = existing.strip()
    body = (preserved + "\n\n" if preserved else "") + "\n".join(generated) + "\n"
    if existing.strip() == body.strip():
        print(f"{requested_tag}: release notes already up to date")
        return

    with tempfile.TemporaryDirectory() as directory:
        notes_file = Path(directory) / "release-notes.md"
        notes_file.write_text(body, encoding="utf-8")
        gh("release", "edit", requested_tag, "--repo", repository, "--notes-file", str(notes_file))
    print(f"{requested_tag}: updated with {len(commits)} linked commits since {previous}")


if __name__ == "__main__":
    main()
